  /* faq */
  "faq.askUsDirectly": "Ask us directly",
  "faq.barcodeLookupIsBuilt": "Barcode lookup is built against an open food database, but the catalogue is uneven outside common packaged products. When a scan finds nothing, the app says so rather than guessing at the numbers.",
  "faq.canIChooseMy": "Can I choose my own coach from a list?",
  "faq.canIScanBarcodes": "Can I scan barcodes when logging food?",
